<script setup lang="ts">
import {paymentSchema} from '@brightloop/shared'
import type {Row} from '~/utils/resources'
const props=defineProps<{portal?:boolean}>(),route=useRoute(),api=useApi(),toast=useToast()
const endpoint=computed(()=>`${props.portal?'/portal/billing':''}/invoices/${route.params.id}`)
const {data:inv,error,refresh}=await useFetch<Row>(()=>'/api'+endpoint.value)
const busy=ref(false),open=ref(false),formError=ref(''), paymentKey=ref(crypto.randomUUID())
const payment=reactive({invoiceId:String(route.params.id),method:'BANK_TRANSFER',amount:'',date:new Date().toISOString().slice(0,10),note:''})
async function action(kind:string){busy.value=true;try{await api(endpoint.value+'/'+kind,{method:'POST',headers:{'Idempotency-Key':paymentKey.value},body:props.portal?{method:'CARD'}:{}});await refresh();toast.add({title:'Invoice updated',color:'success'})}catch(e){toast.add({title:errorMessage(e),color:'error'})}finally{busy.value=false}}
async function save(){busy.value=true;formError.value='';try{const r=paymentSchema.safeParse(payment);if(!r.success){formError.value=r.error.issues.map(i=>i.message).join('; ');return}await api('/payments',{method:'POST',headers:{'Idempotency-Key':paymentKey.value},body:payment});open.value=false;paymentKey.value=crypto.randomUUID();await refresh()}catch(e){formError.value=errorMessage(e)}finally{busy.value=false}}
function print(){window.print()}
</script>
<template><div class="page max-w-5xl"><UAlert v-if="error" color="error" :title="errorMessage(error)"/><template v-if="inv"><div class="page-head no-print"><div><UButton :to="portal?'/portal/billing':'/invoices'" variant="link" class="px-0" icon="i-lucide-arrow-left">Back</UButton><h1>{{inv.number}}</h1></div><div class="flex gap-2 flex-wrap"><UButton variant="outline" color="neutral" icon="i-lucide-printer" @click="print">Print</UButton><template v-if="!portal"><UButton v-if="inv.status==='DRAFT'" :loading="busy" @click="action('confirm')">Confirm invoice</UButton><UButton v-if="['DRAFT','CONFIRMED'].includes(inv.status)&&inv.amountPaid===0" color="error" variant="soft" :loading="busy" @click="action('cancel')">Cancel invoice</UButton><UButton v-if="inv.status==='CONFIRMED'&&!inv.sentAt" variant="outline" color="neutral" icon="i-lucide-send" :loading="busy" @click="action('send')">Send invoice</UButton><UBadge v-else-if="inv.sentAt" variant="subtle" color="success">Sent {{date(inv.sentAt)}}</UBadge><UButton v-if="inv.status==='CONFIRMED'" @click="payment.amount=String(inv.amountDue/100);open=true">Record payment</UButton></template><UButton v-else-if="inv.status==='CONFIRMED'" :loading="busy" @click="action('pay')">Simulate payment</UButton></div></div><UCard><div class="p-2 sm:p-6"><div class="flex justify-between items-start mb-10"><div><p class="text-2xl font-semibold tracking-tight">brightloop.</p><p class="text-sm text-muted mt-2">Brightloop Software</p></div><div class="text-right"><h2 class="text-3xl font-light">INVOICE</h2><p class="text-sm text-muted mt-2">{{inv.number}}</p><UBadge variant="subtle" class="mt-3">{{inv.status}}</UBadge></div></div><div class="flex justify-between flex-wrap gap-6 mb-10"><div><p class="text-xs uppercase tracking-wide text-muted mb-2">Billed to</p><p class="font-medium">{{inv.customer.name}}</p><p class="text-sm text-muted">{{inv.customer.company}}</p><p class="text-sm text-muted">{{inv.customer.email}}</p><p class="text-sm text-muted whitespace-pre-line">{{inv.customer.address}}</p></div><div class="text-sm space-y-2"><p>Issued: {{date(inv.issueDate)}}</p><p>Due: {{date(inv.dueDate)}}</p><p v-if="inv.periodStart" class="text-muted">{{date(inv.periodStart)}} – {{date(inv.periodEnd)}}</p></div></div><div class="overflow-x-auto"><table class="w-full text-sm"><thead><tr class="border-b border-default text-muted text-left"><th class="py-3 font-medium">Description</th><th class="text-right">Qty</th><th class="text-right">Unit price</th><th class="text-right">Tax</th><th class="text-right">Amount</th></tr></thead><tbody><tr v-for="l in inv.lines" :key="l.id" class="border-b border-default"><td class="py-4 pr-4">{{l.description}}<p v-if="l.discount" class="text-xs text-muted">Discount: {{money(l.discount)}} {{l.discountLabel}}</p></td><td class="text-right">{{l.quantity}}</td><td class="text-right whitespace-nowrap">{{money(l.unitPrice)}}</td><td class="text-right">{{l.taxRate}}%</td><td class="text-right whitespace-nowrap">{{money(l.total)}}</td></tr></tbody></table></div><div class="ml-auto w-full sm:w-72 mt-8 space-y-3 text-sm"><div class="flex justify-between"><span class="text-muted">Subtotal</span><span>{{money(inv.subtotal)}}</span></div><div class="flex justify-between"><span class="text-muted">Discount</span><span>−{{money(inv.discountTotal)}}</span></div><div class="flex justify-between"><span class="text-muted">Tax</span><span>{{money(inv.taxTotal)}}</span></div><div class="flex justify-between font-semibold border-t border-default pt-3"><span>Total</span><span>{{money(inv.total)}}</span></div><div class="flex justify-between"><span class="text-muted">Paid</span><span>{{money(inv.amountPaid)}}</span></div><div class="flex justify-between text-lg font-semibold bg-primary/5 p-4 rounded-lg"><span>Amount due</span><span>{{money(inv.amountDue)}}</span></div></div></div></UCard><UCard v-if="inv.payments.length" class="mt-6"><template #header><h2 class="font-semibold">Payments received</h2></template><div v-for="p in inv.payments" :key="p.id" class="flex justify-between py-3 text-sm"><span>{{date(p.date)}} · {{p.method}}</span><span>{{money(p.amount)}}</span></div></UCard></template><UModal v-model:open="open" title="Record payment"><template #body><form class="space-y-4" @submit.prevent="save"><UAlert v-if="formError" color="error" :title="formError"/><UFormField label="Amount (₹)"><UInput v-model="payment.amount" type="number" step="0.01" class="w-full"/></UFormField><UFormField label="Method"><USelect v-model="payment.method" :items="['BANK_TRANSFER','CARD','UPI','CASH','CHEQUE','OTHER']" class="w-full"/></UFormField><UFormField label="Date"><UInput v-model="payment.date" type="date" class="w-full"/></UFormField><UFormField label="Note"><UTextarea v-model="payment.note" class="w-full"/></UFormField><UButton type="submit" :loading="busy" block>Record payment</UButton></form></template></UModal></div></template>
